R,C=26,29
pts={0:[2],4:[3,5],5:[16],6:[18],7:[15],8:[5],9:[16],10:[25],11:[0,16],12:[6],13:[12],14:[20,24],16:[6],17:[14,17],18:[13],19:[14,27],20:[21],22:[22,28],25:[8]}
g=[[2]*C for _ in range(R)]
for r,cs in pts.items():
 for c in cs:g[r][c]=6
# connect all marks in each row and col
for r,cs in pts.items():
 if len(cs)>1:
  for c in range(min(cs),max(cs)+1):
   if g[r][c]!=6:g[r][c]=3
for c in range(C):
 rs=[r for r,cs in pts.items() if c in cs]
 if len(rs)>1:
  for r in range(min(rs),max(rs)+1):
   if g[r][c]!=6:g[r][c]=3
print('\n'.join(' '.join(map(str,row)) for row in g))
